  JMenu view=new JMenu("Ver");item(view,"Ajustar lienzo",canvas::fit);item(view,"100%",()->canvas.setZoom(1,new Point(canvas.getWidth()/2,canvas.getHeight()/2)));item(view,"Girar 15°",()->{canvas.rotation+=Math.PI/12;canvas.repaint();});item(view,"Restablecer rotación",()->{canvas.rotation=0;canvas.repaint();});item(view,"Acercar",()->canvas.setZoom(canvas.zoom*1.25,new Point(canvas.getWidth()/2,canvas.getHeight()/2)));item(view,"Alejar",()->canvas.setZoom(canvas.zoom*.8,new Point(canvas.getWidth()/2,canvas.getHeight()/2)));item(view,"7000%",()->canvas.setZoom(70,new Point(canvas.getWidth()/2,canvas.getHeight()/2)));item(view,"Girar 15° izquierda",()->{canvas.rotation-=Math.PI/12;canvas.repaint();});item(view,"Mostrar / ocultar capas",()->{layers.setVisible(!layers.isVisible());revalidate();});bar.add(view);
