  JMenu objects=new JMenu("Objetos / IA");item(objects,"Insertar imagen editable",()->{JFileChooser pick=new JFileChooser();if(pick.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)try{app.velyntora.windows.objects.ObjectEditor.image(this,DesktopFormats.readInteractive(this,pick.getSelectedFile().toPath()),0,0,this::refresh);}catch(Exception error){JOptionPane.showMessageDialog(this,error.toString());}});item(objects,"Editar texto o imagen de la capa",()->{try{app.velyntora.windows.objects.ObjectEditor.existing(this,this::refresh);}catch(Exception error){JOptionPane.showMessageDialog(this,error.toString());}});item(objects,"Rasterizar objeto",()->effect(()->DrawingView.nativeRasterizeImage(DrawingView.nativeActiveLayer())));item(objects,"Remove AI · Eliminar",()->app.velyntora.windows.ai.RemoveAI.apply(this,canvas.removalMask(),()->{canvas.clearRemoval();refresh();}));item(objects,"Limpiar máscara IA",canvas::clearRemoval);item(objects,"Configurar degradado",()->{JComboBox<String> modes=new JComboBox<>(new String[]{"Lineal","Radial","Lineal reflejado","Diamante","Cónico"});modes.setSelectedIndex(canvas.gradientMode);JCheckBox transparent=new JCheckBox("Color primario a transparente",canvas.gradientTransparent);JPanel p=new JPanel(new GridLayout(0,1));p.add(modes);p.add(transparent);if(JOptionPane.showConfirmDialog(this,p,"Degradado",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){canvas.gradientMode=modes.getSelectedIndex();canvas.gradientTransparent=transparent.isSelected();}});item(objects,"Intercambiar colores",()->{int first=canvas.color;canvas.color=canvas.secondary;canvas.secondary=first;status();});bar.add(objects);JMenu layerMenu=new JMenu("Capas");item(layerMenu,"Añadir capa",()->{DrawingView.nativeAddLayer();refresh();});item(layerMenu,"Duplicar capa",()->{DrawingView.nativeLayerAction(0);refresh();});item(layerMenu,"Combinar con la inferior",()->{DrawingView.nativeLayerAction(1);refresh();});item(layerMenu,"Eliminar capa",()->{DrawingView.nativeDeleteLayer();refresh();});bar.add(layerMenu);
  JMenu help=new JMenu("Ayuda");item(help,"Acerca de",()->JOptionPane.showMessageDialog(this,"Velyntora Drawing · Piloto Windows x64\nPowered By Zaskar Startup\nRueda: zoom · Alt+rueda: rotar · Botón central: desplazar\nLínea/Curva: arrastra extremos, añade un punto y pulsa Enter.\nClonar: Alt+clic elige el origen.\nMotor, formatos, objetos editables, efectos y Remove AI disponibles. La presión usa Windows Ink y depende del controlador de la tableta."));bar.add(help);return bar;
